//! pqchat-core plan T12: the bindings check's reference library. `api` is what FRB cannot take from `pqchat-core` itself;
//! `frb_generated` is the generator's glue, written at check time only; the SDK's two secret copy calls and its dispose
//! (`clients/scaas-sdk/ffi/src/lib.rs`, spec §5), repeated here because this library is a sibling of the SDK's: the only way
//! a decrypted content's bytes leave (owner 2026-11-22). An app's one library has them once.
mod api;
// Generated by flutter_rust_bridge (never hand-edited, never committed).
#[allow(clippy::type_complexity)]
mod frb_generated;

/// Copies `len` bytes at `src` into secret `id`: 0, or -1 (an unknown id, another length, a null pointer).
///
/// # Safety
/// `src` points to `len` readable bytes.
#[no_mangle]
pub unsafe extern "C" fn scaas_sdk_secret_write(id: u64, src: *const u8, len: usize) -> i32 {
    if src.is_null() && len > 0 {
        return -1;
    }
    let src = if len == 0 {
        &[][..]
    } else {
        std::slice::from_raw_parts(src, len)
    };
    scaas_ua::wallet::secret_write(id, src).map_or(-1, |()| 0)
}

/// Copies secret `id` into `dst` (capacity `cap`): its length, or -1 (an unknown id, `cap` too small, a null pointer).
///
/// # Safety
/// `dst` points to `cap` writable bytes.
#[no_mangle]
pub unsafe extern "C" fn scaas_sdk_secret_read(id: u64, dst: *mut u8, cap: usize) -> i64 {
    if dst.is_null() && cap > 0 {
        return -1;
    }
    let dst = if cap == 0 {
        &mut [][..]
    } else {
        std::slice::from_raw_parts_mut(dst, cap)
    };
    scaas_ua::wallet::secret_read(id, dst).map_or(-1, |n| i64::try_from(n).unwrap_or(-1))
}

/// Disposes of secret `id` (zeroed, freed): 0, or -1 when unknown.
#[no_mangle]
pub extern "C" fn scaas_sdk_secret_dispose(id: u64) -> i32 {
    if scaas_ua::wallet::secret_dispose(id) {
        0
    } else {
        -1
    }
}
